<?php define('CRM_ROOT', __DIR__); require 'includes/config.php'; require 'includes/Database.php'; $db = Database::getInstance(); try { $db->getConnection()->exec("CREATE TABLE IF NOT EXISTS notas_caso (id INT AUTO_INCREMENT PRIMARY KEY, caso_id INT NOT NULL, titulo VARCHAR(255) NULL, contenido TEXT NOT NULL, tipo ENUM('publica', 'interna') DEFAULT 'interna', created_by INT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);"); echo 'Tabla notas_caso creada correctamente.<br>'; } catch (Exception $e) { echo 'Error creando notas_caso: ' . $e->getMessage() . '<br>'; } try { $db->getConnection()->exec("ALTER TABLE documentos ADD COLUMN nota_id INT NULL AFTER caso_id;"); echo 'Columna nota_id anadida a documentos.<br>'; } catch (Exception $e) { echo 'Info: La columna nota_id ya existe o hubo un error: ' . $e->getMessage() . '<br>'; } echo '¡Base de datos actualizada! Ya puedes volver al CRM.'; ?>
